// =========================================================================
// HELPER UTILITIES
// =========================================================================

// 1. Ambil data bab tertentu
window.getBabData = function(babNumber) {
    var num = parseInt(babNumber);
    return window.MNN1_DATA.find(function(b) { return b.bab === num; }) || null;
};

// 2. Ambil seluruh daftar bab
window.getAllBab = function() {
    return window.MNN1_DATA;
};

// 3. Ambil kosakata berdasarkan kategori (Strict, zero category bleed)
window.getVocabByCategory = function(category, babFilter) {
    var result = [];
    var filterNum = babFilter && babFilter !== 'all' ? parseInt(babFilter) : null;
    
    window.MNN1_DATA.forEach(function(b) {
        if (filterNum && b.bab !== filterNum) return;
        b.vocab.forEach(function(item) {
            if (category === 'all') {
                result.push(Object.assign({ bab: b.bab }, item));
            } else if (item.kategori && item.kategori.indexOf(category) !== -1) {
                result.push(Object.assign({ bab: b.bab }, item));
            }
        });
    });
    return result;
};

window.getVocabByType = function(jenis, babFilter) {
    return window.getVocabByCategory(jenis, babFilter);
};

// 4. Pencarian kosakata global
window.searchVocab = function(query, babFilter) {
    if (!query || !query.trim()) return [];
    var q = query.trim().toLowerCase();
    var result = [];
    var filterNum = babFilter && babFilter !== 'all' ? parseInt(babFilter) : null;

    window.MNN1_DATA.forEach(function(b) {
        if (filterNum && b.bab !== filterNum) return;
        b.vocab.forEach(function(item) {
            var match = (item.kanji && item.kanji.toLowerCase().indexOf(q) !== -1) ||
                        (item.kana && item.kana.toLowerCase().indexOf(q) !== -1) ||
                        (item.romaji && item.romaji.toLowerCase().indexOf(q) !== -1) ||
                        (item.arti && item.arti.toLowerCase().indexOf(q) !== -1);
            if (match) {
                result.push(Object.assign({ bab: b.bab }, item));
            }
        });
    });
    return result;
};

// 5. Text-to-Speech Engine (Web Speech API)
window.speakJapanese = function(text, btnElement) {
    if (!('speechSynthesis' in window)) {
        alert('Browser Anda tidak mendukung Speech Synthesis.');
        return;
    }
    window.speechSynthesis.cancel();
    
    var cleanText = text.replace(/[［（【(].*?[］）】)]/g, '').replace(/[～~]/g, '').trim();
    if (!cleanText) cleanText = text;

    var utterance = new SpeechSynthesisUtterance(cleanText);
    utterance.lang = 'ja-JP';
    utterance.rate = 0.9;

    if (btnElement) {
        btnElement.classList.add('ring-2', 'ring-red-400', 'scale-110');
        utterance.onend = function() {
            btnElement.classList.remove('ring-2', 'ring-red-400', 'scale-110');
        };
        utterance.onerror = function() {
            btnElement.classList.remove('ring-2', 'ring-red-400', 'scale-110');
        };
    }

    window.speechSynthesis.speak(utterance);
};

// 6. Sound Effects Synthesizer (0 Dependency Audio, Leak-free)
var audioCtx = null;
function getAudioCtx() {
    if (!audioCtx) {
        var AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (AudioContextClass) audioCtx = new AudioContextClass();
    }
    if (audioCtx && audioCtx.state === 'suspended') {
        audioCtx.resume();
    }
    return audioCtx;
}

window.playSfx = function(type) {
    try {
        var ctx = getAudioCtx();
        if (!ctx) return;
        if (ctx.state === 'suspended') {
            ctx.resume();
        }
        var now = ctx.currentTime;

        if (type === 'correct') {
            var freqs = [523.25, 659.25, 783.99];
            freqs.forEach(function(f, i) {
                var o = ctx.createOscillator();
                var g = ctx.createGain();
                o.type = 'sine';
                o.frequency.setValueAtTime(f, now + i * 0.07);
                g.gain.setValueAtTime(0.001, now + i * 0.07);
                g.gain.linearRampToValueAtTime(0.2, now + i * 0.07 + 0.02);
                g.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.07 + 0.24);
                g.gain.setValueAtTime(0, now + i * 0.07 + 0.25);
                o.connect(g);
                g.connect(ctx.destination);
                o.start(now + i * 0.07);
                o.stop(now + i * 0.07 + 0.25);
                o.onended = function() {
                    try { o.disconnect(); g.disconnect(); } catch(e) {}
                };
            });
        } else if (type === 'wrong') {
            var osc = ctx.createOscillator();
            var gain = ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(200, now);
            osc.frequency.exponentialRampToValueAtTime(120, now + 0.2);
            gain.gain.setValueAtTime(0.18, now);
            gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.2);
            gain.gain.setValueAtTime(0, now + 0.21);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(now);
            osc.stop(now + 0.21);
            osc.onended = function() {
                try { osc.disconnect(); gain.disconnect(); } catch(e) {}
            };
        } else if (type === 'combo') {
            var osc = ctx.createOscillator();
            var gain = ctx.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(987.77, now);
            osc.frequency.setValueAtTime(1318.51, now + 0.08);
            gain.gain.setValueAtTime(0.2, now);
            gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.3);
            gain.gain.setValueAtTime(0, now + 0.31);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(now);
            osc.stop(now + 0.31);
            osc.onended = function() {
                try { osc.disconnect(); gain.disconnect(); } catch(e) {}
            };
        } else if (type === 'tick' || type === 'uncheck' || type === 'cancel') {
            var osc = ctx.createOscillator();
            var gain = ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(520, now);
            osc.frequency.exponentialRampToValueAtTime(330, now + 0.06);
            gain.gain.setValueAtTime(0.08, now);
            gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.06);
            gain.gain.setValueAtTime(0, now + 0.07);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(now);
            osc.stop(now + 0.07);
            osc.onended = function() {
                try { osc.disconnect(); gain.disconnect(); } catch(e) {}
            };
        }
    } catch(e) {
        console.warn('Audio SFX error:', e);
    }
};

// 7. LocalStorage Progress Management
var STORAGE_KEY_LEARNED = 'nihongo_mnn1_learned_ids';

window.getLearnedVocabIds = function() {
    try {
        return JSON.parse(localStorage.getItem(STORAGE_KEY_LEARNED) || '[]');
    } catch(e) { return []; }
};

window.isVocabLearned = function(id) {
    var list = window.getLearnedVocabIds();
    return list.indexOf(id) !== -1;
};

window.toggleVocabLearned = function(id) {
    var list = window.getLearnedVocabIds();
    var idx = list.indexOf(id);
    if (idx !== -1) {
        list.splice(idx, 1);
    } else {
        list.push(id);
    }
    localStorage.setItem(STORAGE_KEY_LEARNED, JSON.stringify(list));
    return idx === -1;
};

window.getBabProgress = function(babNumber) {
    var bab = window.getBabData(babNumber);
    if (!bab || !bab.vocab.length) return { learned: 0, total: 0, percent: 0 };
    var learnedList = window.getLearnedVocabIds();
    var learned = bab.vocab.filter(function(v) { return learnedList.indexOf(v.id) !== -1; }).length;
    var total = bab.vocab.length;
    return {
        learned: learned,
        total: total,
        percent: Math.round((learned / total) * 100)
    };
};

window.getTotalProgress = function() {
    var totalVocab = 0;
    window.MNN1_DATA.forEach(function(b) { totalVocab += b.vocab.length; });
    var learnedCount = window.getLearnedVocabIds().length;
    return {
        learned: learnedCount,
        total: totalVocab,
        percent: totalVocab > 0 ? Math.round((learnedCount / totalVocab) * 100) : 0
    };
};
